return await (function initialize() {
  const items = $input.all();
  if (items.length !== 1) throw new Error('Collect one existing run per execution.');
  const runId = items[0].json.runId;
  if (typeof runId !== 'string' || !/^[A-Za-z0-9]{17}$/.test(runId)) {
    throw new Error('Set runId to the 17-character ID of an existing Supplier Catalog Comparison run.');
  }
  return [{ json: { runId, actorId: 'mGKOcnAMxtbJ9eAc0', maxChecks: 18 } }];
}).call(this);

return await (function checkRun() {
  const ctx = $('Validate comparison run ID').first().json;
  const response = $input.first().json;
  if (response.statusCode !== 200) throw new Error('Run lookup failed. Resume this same run ID later.');
  const run = response.body?.data;
  if (!run || run.id !== ctx.runId || run.actId !== ctx.actorId) {
    throw new Error('Run or Actor identity mismatch. No output will be collected.');
  }
  const checks = $runIndex + 1;
  if (run.status === 'SUCCEEDED') {
    if (!/^[A-Za-z0-9]{17}$/.test(run.defaultKeyValueStoreId || '')) {
      throw new Error('Missing or invalid output store ID.');
    }
    return [{ json: { ...ctx, checks, status: run.status, storeId: run.defaultKeyValueStoreId } }];
  }
  const pending = ['READY', 'RUNNING', 'TIMING-OUT', 'ABORTING'];
  if (!pending.includes(run.status)) {
    throw new Error('Existing run ended with ' + String(run.status) + '. This workflow never starts a replacement.');
  }
  if (checks >= ctx.maxChecks) {
    throw new Error('Collection paused after 18 checks. Resume the SAME run ID later; the cloud run was not stopped.');
  }
  return [{ json: { ...ctx, checks, status: run.status } }];
}).call(this);

return await (async function exportResult() {
  const ctx = $('Keep successful run context').first().json;
  function body(name) {
    const r = $(name).first().json;
    if (r.statusCode !== 200) throw new Error(name + ' was not available. Resume the same run ID.');
    return r.body;
  }
  const summary = body('Fetch comparison summary');
  const review = body('Fetch review records');
  const documents = []; // Comparison diagnostics are in SUMMARY and REVIEW.
  const csv = body('Fetch comparison CSV');
  if (!summary || typeof summary !== 'object' || Array.isArray(summary) ||
      !Number.isInteger(summary.delivered_rows) || summary.delivered_rows < 0 || summary.delivered_rows > 10000) {
    throw new Error('SUMMARY must contain an integer delivered_rows from 0 to 10000.');
  }
  if (!Array.isArray(review) || !Array.isArray(documents)) throw new Error('Invalid diagnostics format.');
  if (typeof csv !== 'string' || Buffer.byteLength(csv, 'utf8') > 25 * 1024 * 1024) {
    throw new Error('Missing CSV or export exceeds this collector\'s 25 MiB processing limit.');
  }
  // Strict CSV parser: quoted commas/newlines, doubled quotes, CRLF, BOM.
  // Do not split on newlines: supplier descriptions may themselves contain them.
  const text = csv.replace(/^\uFEFF/, '');
  const rows = [];
  let row = [], cell = '', quoted = false, closed = false;
  function field() { row.push(cell); cell = ''; closed = false; }
  function record() { field(); rows.push(row); row = []; }
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (quoted) {
      if (ch === '"') {
        if (text[i + 1] === '"') { cell += '"'; i++; }
        else { quoted = false; closed = true; }
      } else cell += ch;
      continue;
    }
    if (ch === ',') field();
    else if (ch === '\r' || ch === '\n') {
      if (ch === '\r' && text[i + 1] === '\n') i++;
      record();
    } else if (ch === '"' && cell === '' && !closed) quoted = true;
    else {
      if (closed || ch === '"') throw new Error('Malformed CSV quoting.');
      cell += ch;
    }
  }
  if (quoted) throw new Error('Unterminated CSV quoted field.');
  if (row.length || cell.length || closed) record();
  const header = rows.shift();
  if (!header || new Set(header).size !== header.length ||
      !['sku', 'change_type'].every(key => header.includes(key))) {
    throw new Error('CSV lacks the expected unique product headers.');
  }
  if (rows.some(r => r.length !== header.length)) throw new Error('CSV column count mismatch.');
  if (rows.length !== summary.delivered_rows) throw new Error('CSV record count differs from delivered_rows.');
  const flags = [];
  if (summary.budget_stopped) flags.push('spending_limit');
  if (review.length) flags.push('review_records');
  if (summary.status !== 'ok') flags.push('summary_status_' + String(summary.status || 'unknown'));
  if (Array.isArray(summary.issues) && summary.issues.length) flags.push('summary_issues');
  if (documents.some(d => !d || ['failed', 'error'].includes(d.status))) flags.push('document_failures');
  if (rows.some(r => r.some(v => /^[\t\r\n ]*[=+@-]/.test(v)))) flags.push('spreadsheet_formula_like_text');
  const diagnostic = {
    runId: ctx.runId, actorId: ctx.actorId, deliveredRows: rows.length,
    collectionOnly: $('Configure comparison inputs').first().json.mode === 'resume', destinationWriteApproved: false,
    completeness: 'Not independently established; validate destination mapping and exception policy.',
    flags, summary, review, documents,
  };
  return [{
    json: diagnostic,
    binary: {
      products: await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), 'COMPARISON.csv', 'text/csv'),
      diagnostics: await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(diagnostic, null, 2), 'utf8'), 'DIAGNOSTICS.json', 'application/json'),
    },
  }];
}).call(this);

const all=$input.all();if(all.length!==1)throw new Error('One revision per execution.');const c=all[0].json;
if(!['start','resume'].includes(c.mode))throw new Error('Choose start or resume.');
if(c.mode==='resume')return [{json:c}];
if(c.runId && c.runId!=='PASTE_EXISTING_RUN_ID')throw new Error('Existing run ID present: choose resume.');
if(c.confirmation!=='START_ONE_COMPARISON')throw new Error('Set confirmation to START_ONE_COMPARISON only after checking that this revision has not already run.');
if(typeof c.revision!=='string'||!c.revision.trim()||c.revision.length>120)throw new Error('Set a supplier revision label. This is NOT an automatic deduplication lock.');
for(const key of ['beforePdfUrl','afterPdfUrl']){if(typeof c[key]!=='string'||!/^https:\/\/[A-Za-z0-9.-]+(?::443)?(?:\/[^\s]*)?$/.test(c[key]))throw new Error('Use authorized public HTTPS documents without URL credentials.');}
if(c.beforePdfUrl===c.afterPdfUrl)throw new Error('Use two different catalog revisions.');
if(!['USD','CAD','AUD','EUR','GBP'].includes(c.currency)||!['decimal-dot','decimal-comma'].includes(c.numberFormat))throw new Error('Choose a supported currency and number format.');
if(!Number.isInteger(c.maxPages)||c.maxPages<1||c.maxPages>20)throw new Error('Choose 1 to 20 pages.');
if(typeof c.maxTotalChargeUsd!=='number'||!Number.isFinite(c.maxTotalChargeUsd)||c.maxTotalChargeUsd<0.005||c.maxTotalChargeUsd>1)throw new Error('This starter accepts a positive budget from $0.005 to $1.');
return [{json:{...c,input:{beforePdfUrl:c.beforePdfUrl,afterPdfUrl:c.afterPdfUrl,currency:c.currency,numberFormat:c.numberFormat,maxPages:c.maxPages,beforeTableMode:'ruled',afterTableMode:'ruled'}}}];

const r=$input.first().json;const run=r.body?.data;const c=$('Validate mode and start settings').first().json;
if(![200,201].includes(r.statusCode)||!run||!/^[A-Za-z0-9]{17}$/.test(run.id||'')||run.actId!=='mGKOcnAMxtbJ9eAc0')throw new Error('Start outcome uncertain. Reconcile in Apify Console; do not start again.');
if(run.options?.maxTotalChargeUsd!==c.maxTotalChargeUsd)throw new Error('Accepted budget mismatch for run '+run.id+'. Inspect this run in Console; do not restart.');
return [{json:{runId:run.id,revision:c.revision,acceptedBudget:c.maxTotalChargeUsd,recovery:'Save this ID outside execution history. Resume this same ID after collection errors.'}}];
